<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/bootstrap/app.php';
$admin=pf_require_admin($pdo);$error='';$notice='';$syncCampaignId=0;$syncAction='';
if($_SERVER['REQUEST_METHOD']==='POST'){
 pf_verify_csrf();$action=(string)($_POST['action']??'');$id=filter_var($_POST['id']??null,FILTER_VALIDATE_INT);$decision=(string)($_POST['decision']??'');$note=trim((string)($_POST['note']??''));
 if(!$id)$error='Invalid record.';else{$pdo->beginTransaction();try{
  if($action==='funding'){
   $q=$pdo->prepare('SELECT * FROM pf_funding_requests WHERE id=? FOR UPDATE');$q->execute([$id]);$r=$q->fetch();if(!$r||$r['status']!=='PENDING'||!in_array($decision,['approve','reject'],true))throw new RuntimeException('Funding request is no longer pending.');
   if($decision==='approve'){
    $pdo->prepare("INSERT IGNORE INTO pf_wallets(user_id,wallet_type,currency) VALUES (?,'ADVERTISER',?)")->execute([(int)$r['advertiser_id'],$r['currency']]);$w=$pdo->prepare("SELECT id FROM pf_wallets WHERE user_id=? AND wallet_type='ADVERTISER' AND currency=? FOR UPDATE");$w->execute([(int)$r['advertiser_id'],$r['currency']]);$wid=(int)$w->fetchColumn();
    $l=$pdo->prepare("INSERT INTO pf_wallet_ledger(wallet_id,user_id,entry_type,amount,currency,reference_type,reference_id,idempotency_key,description,created_by) VALUES (?,?,'DEPOSIT',?,?,'FUNDING_REQUEST',?,?,?,?)");$l->execute([$wid,(int)$r['advertiser_id'],$r['amount'],$r['currency'],$id,'funding-request-'.$id,'Verified advertiser deposit',(int)$admin['id']]);$lid=(int)$pdo->lastInsertId();
    $u=$pdo->prepare("UPDATE pf_funding_requests SET status='APPROVED',ledger_entry_id=?,reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE id=? AND status='PENDING'");$u->execute([$lid,(int)$admin['id'],$note?:null,$id]);if($u->rowCount()!==1)throw new RuntimeException('Funding request changed during approval.');
   }else{$pdo->prepare("UPDATE pf_funding_requests SET status='REJECTED',reviewed_by=?,reviewed_at=NOW(),review_note=? WHERE id=? AND status='PENDING'")->execute([(int)$admin['id'],$note?:null,$id]);}
  }elseif($action==='campaign'){
   $q=$pdo->prepare("SELECT c.*,u.status user_status,p.status advertiser_status FROM pf_campaigns c JOIN users u ON u.id=c.advertiser_id JOIN pf_advertiser_profiles p ON p.user_id=c.advertiser_id WHERE c.id=? AND c.campaign_type IN ('SITE_DISPLAY','BLOG_SPONSORED') FOR UPDATE");$q->execute([$id]);$c=$q->fetch();if(!$c||$c['status']!=='PENDING_REVIEW'||!in_array($decision,['approve','reject'],true))throw new RuntimeException('Campaign is no longer awaiting review.');
   if($decision==='approve'){
    if($c['user_status']!=='ACTIVE'||$c['advertiser_status']!=='ACTIVE')throw new RuntimeException('An inactive advertiser cannot publish a campaign.');
    if($c['campaign_type']==='SITE_DISPLAY'){$r=$pdo->prepare("SELECT amount FROM pf_site_campaign_reservations WHERE campaign_id=? AND status='RESERVED' FOR UPDATE");$r->execute([$id]);$amount=$r->fetchColumn();if($amount===false||abs((float)$amount-(float)$c['reserved_budget'])>0.01)throw new RuntimeException('Main-site campaign budget reservation does not match.');$pdo->prepare("UPDATE pf_site_campaigns SET status='ACTIVE' WHERE campaign_id=?")->execute([$id]);}
    else{$r=$pdo->prepare("SELECT amount FROM pf_blog_campaign_reservations WHERE campaign_id=? AND status='RESERVED' FOR UPDATE");$r->execute([$id]);$amount=$r->fetchColumn();if($amount===false||abs((float)$amount-(float)$c['reserved_budget'])>0.01)throw new RuntimeException('Blog campaign budget reservation does not match.');$pdo->prepare("UPDATE pf_blog_campaigns SET status='ACTIVE',sync_status='PENDING',last_sync_error=NULL WHERE campaign_id=?")->execute([$id]);$syncCampaignId=(int)$id;$syncAction='upsert';}
    $pdo->prepare("UPDATE pf_campaigns SET status='ACTIVE',reviewed_by=?,reviewed_at=NOW(),admin_note=? WHERE id=?")->execute([(int)$admin['id'],$note?:null,$id]);
   }else{
    $table=$c['campaign_type']==='SITE_DISPLAY'?'pf_site_campaign_reservations':'pf_blog_campaign_reservations';$refType=$c['campaign_type']==='SITE_DISPLAY'?'SITE_CAMPAIGN':'BLOG_CAMPAIGN';$prefix=$c['campaign_type']==='SITE_DISPLAY'?'site-campaign-release-':'blog-campaign-release-';
    $r=$pdo->prepare("SELECT id,amount,advertiser_id,currency FROM {$table} WHERE campaign_id=? AND status='RESERVED' FOR UPDATE");$r->execute([$id]);$res=$r->fetch();if(!$res||abs((float)$res['amount']-(float)$c['reserved_budget'])>0.01)throw new RuntimeException('Campaign reservation does not match. Rejection was rolled back for reconciliation.');
    $w=$pdo->prepare("SELECT id FROM pf_wallets WHERE user_id=? AND wallet_type='ADVERTISER' AND currency=? FOR UPDATE");$w->execute([(int)$res['advertiser_id'],$res['currency']]);$wid=(int)$w->fetchColumn();if(!$wid)throw new RuntimeException('Advertiser wallet is missing.');
    $l=$pdo->prepare("INSERT INTO pf_wallet_ledger(wallet_id,user_id,entry_type,amount,currency,reference_type,reference_id,idempotency_key,description,created_by) VALUES (?,?,'CAMPAIGN_RELEASE',?,?,?,?,?,?,?)");$l->execute([$wid,(int)$res['advertiser_id'],$res['amount'],$res['currency'],$refType,$id,$prefix.$id,'Released rejected campaign budget',(int)$admin['id']]);
    $pdo->prepare("UPDATE {$table} SET status='RELEASED' WHERE id=? AND status='RESERVED'")->execute([(int)$res['id']]);$pdo->prepare("UPDATE pf_campaigns SET status='REJECTED',reserved_budget=0,reviewed_by=?,reviewed_at=NOW(),admin_note=? WHERE id=?")->execute([(int)$admin['id'],$note?:null,$id]);
    if($c['campaign_type']==='SITE_DISPLAY')$pdo->prepare("UPDATE pf_site_campaigns SET status='REVOKED' WHERE campaign_id=?")->execute([$id]);else{$pdo->prepare("UPDATE pf_blog_campaigns SET status='REVOKED',sync_status='PENDING' WHERE campaign_id=?")->execute([$id]);$syncCampaignId=(int)$id;$syncAction='revoke';}
   }
  }elseif($action==='blog_sync_retry'){
   $q=$pdo->prepare("SELECT c.status,bc.status blog_status,bc.sync_status FROM pf_campaigns c JOIN pf_blog_campaigns bc ON bc.campaign_id=c.id WHERE c.id=? AND c.campaign_type='BLOG_SPONSORED' FOR UPDATE");$q->execute([$id]);$r=$q->fetch();
   if(!$r||$r['sync_status']!=='FAILED')throw new RuntimeException('This blog campaign does not have a failed synchronization to retry.');
   if($r['status']==='ACTIVE')$pdo->prepare("UPDATE pf_campaigns SET status='PAUSED' WHERE id=?")->execute([$id]);
   if($r['blog_status']==='ACTIVE')$pdo->prepare("UPDATE pf_blog_campaigns SET status='PAUSED' WHERE campaign_id=?")->execute([$id]);
   $syncCampaignId=(int)$id;$syncAction='revoke';
  }else throw new RuntimeException('Unknown administrator action.');
  $ip=(string)($_SERVER['REMOTE_ADDR']??'');$ipBin=filter_var($ip,FILTER_VALIDATE_IP)?inet_pton($ip):null;$pdo->prepare('INSERT INTO pf_audit_log(actor_user_id,action,subject_type,subject_id,after_json,ip_address) VALUES (?,?,?,?,?,?)')->execute([(int)$admin['id'],'ADMIN_'.strtoupper($action),strtoupper($action),$id,json_encode(['decision'=>$decision,'note'=>$note]),$ipBin]);
  $pdo->commit();$notice='The administrator action has been recorded.';
  if($syncCampaignId>0){$sync=pf_sync_blog_campaign($pdo,$syncCampaignId,$syncAction);if($sync['ok']){$pdo->prepare("UPDATE pf_blog_campaigns SET sync_status='SYNCED',last_sync_error=NULL WHERE campaign_id=?")->execute([$syncCampaignId]);$notice='Blog campaign action completed and synchronization succeeded.';}elseif($syncAction==='upsert'){$pdo->beginTransaction();$pdo->prepare("UPDATE pf_campaigns SET status='PAUSED' WHERE id=?")->execute([$syncCampaignId]);$pdo->prepare("UPDATE pf_blog_campaigns SET status='PAUSED',sync_status='FAILED',last_sync_error=? WHERE campaign_id=?")->execute([$sync['error'],$syncCampaignId]);$pdo->commit();pf_sync_blog_campaign($pdo,$syncCampaignId,'revoke');$error='The campaign action was saved, but blog synchronization failed. The campaign remains paused.';}else{$pdo->prepare("UPDATE pf_blog_campaigns SET sync_status='FAILED',last_sync_error=? WHERE campaign_id=?")->execute([$sync['error'],$syncCampaignId]);}}
 }catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$error=$e instanceof RuntimeException?$e->getMessage():'The action failed and was rolled back.';}}
}
$payments=$pdo->query("SELECT p.provider,p.provider_reference,p.amount,p.currency,p.status,p.created_at,u.name,u.email FROM pf_payment_orders p JOIN users u ON u.id=p.advertiser_id ORDER BY p.id DESC LIMIT 100")->fetchAll();
$fund=$pdo->query("SELECT f.*,u.name,u.email FROM pf_funding_requests f JOIN users u ON u.id=f.advertiser_id WHERE f.status='PENDING' ORDER BY f.id LIMIT 100")->fetchAll();
$campaigns=$pdo->query("SELECT c.id,c.title,c.status,c.currency,c.reserved_budget,c.campaign_type,u.name advertiser_name,sc.placement_key site_placement,sc.starts_at site_start,sc.ends_at site_end,bc.placement_key blog_placement,bc.starts_at blog_start,bc.ends_at blog_end FROM pf_campaigns c JOIN users u ON u.id=c.advertiser_id LEFT JOIN pf_site_campaigns sc ON sc.campaign_id=c.id LEFT JOIN pf_blog_campaigns bc ON bc.campaign_id=c.id WHERE c.campaign_type IN ('SITE_DISPLAY','BLOG_SPONSORED') AND c.status='PENDING_REVIEW' ORDER BY c.id LIMIT 100")->fetchAll();
$failed=$pdo->query("SELECT c.id,c.title,u.name advertiser_name,bc.placement_key,bc.last_sync_error FROM pf_campaigns c JOIN users u ON u.id=c.advertiser_id JOIN pf_blog_campaigns bc ON bc.campaign_id=c.id WHERE c.campaign_type='BLOG_SPONSORED' AND bc.sync_status='FAILED' ORDER BY c.id LIMIT 100")->fetchAll();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Finance & campaign review | PoketFlow</title><link rel="stylesheet" href="../assets/marketplace.css"><style>.review{padding:16px 0;border-top:1px solid var(--line)}.stack{display:flex;gap:8px;flex-wrap:wrap;margin-top:10px}.stack input{padding:10px;border:1px solid var(--line);border-radius:10px}.section{margin-top:22px}.danger{background:#fff1f2;color:#9f1239}</style></head><body><header class="topbar"><a class="brand" href="../index.php"><span class="brand-mark">P</span><span>Poket<span>Flow</span></span></a><nav><a href="index.php">Admin home</a><a href="advertisers.php">Advertisers</a><a href="campaigns.php">Campaigns</a><a href="placements.php">Placements</a><a href="users.php">Members</a><a href="../dashboard.php">Dashboard</a><a href="../logout.php">Sign out</a></nav></header><main class="container"><section class="welcome"><p class="eyebrow">ADMINISTRATION</p><h1>Payments & campaign moderation</h1><p class="muted">Verify advertiser funding, review reserved campaign budgets and resolve blog synchronization failures. Worker payouts and task moderation are not part of this product.</p></section><?php if($error):?><div class="alert"><?=pf_e($error)?></div><?php endif;?><?php if($notice):?><div class="panel"><?=pf_e($notice)?></div><?php endif;?>
<section class="panel section"><h2>Online payment records</h2><p class="small muted">Provider payments are verified server-side before advertiser wallet credit. Do not manually mark online orders as paid.</p><div style="overflow:auto"><table style="width:100%;border-collapse:collapse;text-align:left"><thead><tr><th>Advertiser</th><th>Provider</th><th>Reference</th><th>Amount</th><th>Status</th><th>Date</th></tr></thead><tbody><?php foreach($payments as $p):?><tr><td><?=pf_e($p['name'])?> · <?=pf_e($p['email'])?></td><td><?=pf_e($p['provider'])?></td><td><?=pf_e($p['provider_reference'])?></td><td><?=pf_e($p['currency'])?> <?=number_format((float)$p['amount'],2)?></td><td><?=pf_e($p['status'])?></td><td><?=pf_e($p['created_at'])?></td></tr><?php endforeach;?><?php if(!$payments):?><tr><td colspan="6">No online payment records.</td></tr><?php endif;?></tbody></table></div></section>
<section class="panel section"><h2>Legacy manual funding requests</h2><?php foreach($fund as $r):?><div class="review"><strong><?=pf_e($r['name'])?></strong> · <?=pf_e($r['email'])?><p><?=pf_e($r['currency'])?> <?=number_format((float)$r['amount'],2)?> · <?=pf_e($r['payment_method'])?> · Ref: <?=pf_e((string)$r['payer_reference'])?></p><?php if($r['proof_url']):?><p><a href="<?=pf_e($r['proof_url'])?>" target="_blank" rel="noopener">View payment proof</a></p><?php endif;?><form class="stack" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="action" value="funding"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="note" placeholder="Admin note"><button class="button primary" name="decision" value="approve">Verify & credit wallet</button><button class="button danger" name="decision" value="reject">Reject</button></form></div><?php endforeach;?><?php if(!$fund):?><p class="muted">No pending funding requests.</p><?php endif;?></section>
<section class="panel section"><h2>Campaigns awaiting review</h2><?php foreach($campaigns as $r):?><div class="review"><strong><?=pf_e($r['title'])?></strong> · <?=pf_e($r['advertiser_name'])?><p><?= $r['campaign_type']==='SITE_DISPLAY'?'Main-site placement: '.pf_e((string)$r['site_placement']):'Blog placement: '.pf_e((string)$r['blog_placement']) ?> · <?=pf_e($r['currency'])?> <?=number_format((float)$r['reserved_budget'],2)?> reserved</p><p class="small muted">Dates: <?=pf_e(substr((string)($r['site_start']??$r['blog_start']),0,10))?> – <?=pf_e(substr((string)($r['site_end']??$r['blog_end']),0,10))?></p><form class="stack" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="action" value="campaign"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input name="note" placeholder="Moderation note"><button class="button primary" name="decision" value="approve">Approve & publish</button><button class="button danger" name="decision" value="reject">Reject & release budget</button></form></div><?php endforeach;?><?php if(!$campaigns):?><p class="muted">No campaigns awaiting review.</p><?php endif;?></section>
<section class="panel section"><h2>Blog campaigns needing sync retry</h2><?php foreach($failed as $r):?><div class="review"><strong><?=pf_e($r['title'])?></strong> · <?=pf_e($r['advertiser_name'])?><p><?=pf_e($r['placement_key'])?> · <?=pf_e((string)$r['last_sync_error'])?></p><form class="stack" method="post"><input type="hidden" name="_token" value="<?=pf_e(pf_csrf_token())?>"><input type="hidden" name="action" value="blog_sync_retry"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><button class="button primary" type="submit">Retry blog sync</button></form></div><?php endforeach;?><?php if(!$failed):?><p class="muted">No failed blog syncs.</p><?php endif;?></section></main></body></html>
